import json, subprocess, sys
def plan(flows, caps, offers, pinned=[], warmup=0):
    req = dict(mode='plan', capacities=caps, flows=flows, warmup=warmup, pinned=pinned, offers=offers)
    r = subprocess.run([sys.executable,'-I','-B','/workspace/submission/main.py'], input=json.dumps(req)+'\n',
                       capture_output=True, text=True)
    return json.loads(r.stdout)
def F(fid, path, count, H=16):
    kinds = list('K'*H); kinds[5]='Q'; kinds[6]='T'; kinds[7]='D'
    hdr = '00'*(H-8) + '00'*0
    b = bytearray(H)
    b[5]=3; b[6]=250
    return dict(id=fid, path=path, template='00'*H, kinds=''.join(kinds)), bytes(b).hex()
def mk(fid, path, count):
    f, hdr = F(fid, path, count)
    return f, [dict(header=hdr, count=count)]
